* glue.s - integration of the (relocated, patched) arcade program with the Neo Geo runtime.
*
*   game_main   : entered from USER (demo/title request): sets up the I/O shadow and jumps to the
*                 arcade reset entry 0x2400 (its SSP is relocated to ARC_WRAM+0x3F80 by the patcher).
*   frame_hook  : called from our VBlank handler after SYSTEM_IO: feeds the inputs, runs the arcade
*                 VBlank handler (0x2F8C) on the runtime stack, then syncs palette/tiles/sprites.
*   mcu_frame   : in mcu.s.
*   oracle stubs: generated by tools/mkrom.py into build/stubs.s.

        .include "neogeo.i"
        .include "ram.i"

        .text
        .global game_main, sound_init, frame_hook, trap1_handler, main_wait, arc_sound_tick, srch_hook

        .equ    ARC_RESET,      0x2400
        .equ    ARC_IRQ6,       0x2F8C
        .equ    ARC_SNDSEQ,     0x14122         /* sound sequencer, called by the arcade interrupt at 0x2FFE */
        .equ    ARC_WRAM_STACK, ARC_WRAM+0x3F80

* ---- arcade input word (700002/3), active low ----
        .equ    ARC_P1_UP,      0
        .equ    ARC_P1_DOWN,    1
        .equ    ARC_P1_RIGHT,   2
        .equ    ARC_P1_LEFT,    3
        .equ    ARC_P1_GEAR,    4
        .equ    ARC_P1_ACCEL,   5
        .equ    ARC_COIN1,      6
        .equ    ARC_COIN2,      7
        .equ    ARC_START1,     14
        .equ    ARC_START2,     15

sound_init:
        jmp     snd_init

game_main:
        bsr     io_init
        clr.b   rt_in_game
        clr.b   rt_gear
        clr.b   rt_coin_pulse
        clr.b   rt_start_pulse
        clr.b   rt_start_req
        bsr     selftest_decrypt
        st      rt_arcade_on
        jmp     ARC_RESET

* I/O shadow defaults: DSW = 0xFFDF (MAME defaults: joystick, 2 sticks, normal, demo sounds on, 1C/1C),
* inputs idle, SYSTEM idle, wheel idle.
io_init:
        move.w  #0xFFDF,IO_DSW
        move.w  #0xFFFF,IO_P1P2
        move.w  #0x00FF,IO_WHEEL
        move.w  #0xFFF3,IO_SYSTEM
        rts

* Build the arcade input word from the Neo Geo controls (BIOS_P1CURRENT: bit0 up,1 down,2 left,3 right,
* 4 A,5 B,6 C,7 D, active high after SYSTEM_IO).  A = accelerate, B = gear toggle, C = accelerate too.
io_update:
        move.w  #0xFFFF,d0              /* idle; the gear bit (4) reads 1 at power-on on the arcade (MAME default) */
        move.b  BIOS_P1CURRENT,d1
        btst    #0,d1
        beq.s   1f
        bclr    #ARC_P1_UP,d0
1:      btst    #1,d1
        beq.s   2f
        bclr    #ARC_P1_DOWN,d0
2:      btst    #2,d1
        beq.s   3f
        bclr    #ARC_P1_LEFT,d0
3:      btst    #3,d1
        beq.s   4f
        bclr    #ARC_P1_RIGHT,d0
4:      move.b  d1,d2
        and.b   #0x50,d2                /* A or C */
        beq.s   5f
        bclr    #ARC_P1_ACCEL,d0
5:      /* gear toggle on B press (edge) */
        move.b  d1,d2
        and.b   #0x20,d2
        move.b  rt_prev_b,d3
        move.b  d2,rt_prev_b
        tst.b   d3
        bne.s   6f
        tst.b   d2
        beq.s   6f
        eori.b  #1,rt_gear
6:      tst.b   rt_gear
        beq.s   7f
        bclr    #ARC_P1_GEAR,d0
7:      /* ---- credits: on MVS the BIOS owns them (backup RAM 0xD00034, BCD); mirror every increment
           into the arcade as a coin pulse so its own counter stays in sync ---- */
        tst.b   BIOS_MVS_FLAG
        beq     8f
        move.b  0xD00034,d1
        cmp.b   rt_bios_cred,d1
        beq     8f
        move.b  d1,d2
        sub.b   rt_bios_cred,d2         /* BCD difference is fine for small steps */
        move.b  d1,rt_bios_cred
        tst.b   d2
        ble     8f
        add.b   d2,rt_coins_due
8:      /* PLAYER_START seen: on AES inject a coin first, then hold START until the arcade takes a credit */
        tst.b   rt_start_req
        beq     9f
        clr.b   rt_start_req
        moveq   #1,d1                   /* MVS: coin already mirrored, start right away */
        tst.b   BIOS_MVS_FLAG
        bne     81f
        addq.b  #1,rt_coins_due
        moveq   #90,d1                  /* AES: let the arcade credit the coin and fade to its prompt */
81:     move.b  d1,rt_start_wait
        move.w  #240,rt_start_hold
        move.w  ARC_WRAM+0x1EE,rt_cred_start
9:      /* coin pulse: 3 frames pressed, 12 released */
        move.b  rt_coin_seq,d1
        bne     91f
        tst.b   rt_coins_due
        beq     92f
        subq.b  #1,rt_coins_due
        moveq   #1,d1
91:     cmpi.b  #3,d1
        bhi     93f
        bclr    #ARC_COIN1,d0
93:     addq.b  #1,d1
        cmpi.b  #15,d1
        bcs     94f
        moveq   #0,d1
94:     move.b  d1,rt_coin_seq
92:     /* START: raw button, or the hold after PLAYER_START */
        move.b  BIOS_STATCURNT,d1
        btst    #0,d1
        beq     10f
        bclr    #ARC_START1,d0
10:     tst.w   rt_start_hold
        beq     11f
        tst.b   rt_start_wait
        beq     101f
        subq.b  #1,rt_start_wait
        bra     11f
101:    move.w  ARC_WRAM+0x1EE,d1
        cmp.w   rt_cred_start,d1
        bcs     102f                    /* the arcade took the credit: done */
        subq.w  #1,rt_start_hold
        move.w  rt_start_hold,d1
        btst    #3,d1                   /* 8 frames pressed, 8 released: the arcade wants a fresh edge */
        bne     11f
        bclr    #ARC_START1,d0
        bra     11f
102:    clr.w   rt_start_hold
11:     move.w  d0,IO_P1P2
        rts

* frame_hook: runs inside our VBlank handler (all registers saved by the caller)
* ------------------------------------------------------------------------------------------
* main_wait: replaces every "tst.w C1A6 / beq.s *-6" loop of the arcade (wait for the next interrupt
* tick).  Runs a tick that the VBlank held back because the frame was not finished (see irq_vblank),
* otherwise waits for the next one.  Preserves all registers; the code after it clears C1A6 as before.
* ------------------------------------------------------------------------------------------
main_wait:
        clr.b   rt_mw_age
        move    sr,-(sp)
        ori     #0x0700,sr
        tst.b   rt_tick_pend
        bne.s   2f
        st      rt_mwait                /* (with the interrupts masked: no tick can be held back in between) */
        move    (sp)+,sr
1:      addq.l  #1,rt_idle              /* profiling: 54 cycles per iteration */
        tst.w   ARC_WRAM+0x1A6
        beq.s   1b
        sf      rt_mwait
        rts
2:      subq.b  #1,rt_tick_pend
        st      rt_in_hook              /* a VBlank meanwhile only flushes the VRAM (irq_vblank) */
        move    (sp),sr
        movem.l d0-d7/a0-a6,-(sp)
        jsr     frame_hook
        clr.b   rt_in_hook
        movem.l (sp)+,d0-d7/a0-a6
        move    (sp)+,sr
        rts

* ------------------------------------------------------------------------------------------
* srch_hook (jmp at 0xA07A): the arcade looks for the record of key d0 in the table at a1, one compare
* per record ("cmp.w (a1),d0 / beq / skip to $00FF / next").  With the index of tools/mksrch.py the
* record is found at once; anything not in the index takes the original loop.  Continues at 0xA08C with
* a1 -> the key word, as the original; only a1 changes.
* ------------------------------------------------------------------------------------------
srch_hook:
        cmpi.w  #64,d0
        bcc.s   9f
        movem.l d0-d1/a0,-(sp)
        lea     srch_tabs,a0
        moveq   #3,d1
1:      cmpa.l  (a0)+,a1
        beq.s   2f
        dbra    d1,1b
        bra.s   8f                      /* not one of the four tables */
2:      neg.w   d1
        addq.w  #3,d1                   /* table number */
        lsl.w   #8,d1
        and.w   #0x3F,d0
        lsl.w   #2,d0
        add.w   d0,d1
        lea     srch_idx,a0
        move.l  (a0,d1.w),d1
        beq.s   8f                      /* not indexed: the loop */
        movea.l d1,a1
        movem.l (sp)+,d0-d1/a0
        jmp     0xA08C
8:      movem.l (sp)+,d0-d1/a0
9:      cmp.w   (a1),d0                 /* the original loop */
        beq.s   1f
2:      addq.l  #2,a1
        cmpi.w  #0xFF,(a1)
        bne.s   2b
        addq.l  #2,a1
        bra.s   9b
1:      jmp     0xA08C
srch_tabs:
        .long   0xE15B2, 0xE1A12, 0xE1382, 0xE17E2
srch_idx:
        .include "srch_idx.inc"

* arc_sound_tick: the arcade sound sequencer (called once per arcade interrupt at 0x2FFE, moved here so
* that it runs every VBlank even when a tick is held back)
arc_sound_tick:
        tst.b   rt_arcade_on
        beq.s   1f
        movem.l d0-d7/a0-a6,-(sp)
        jsr     ARC_SNDSEQ
        movem.l (sp)+,d0-d7/a0-a6
1:      rts

frame_hook:
        move.w  REG_LSPCMODE,rt_dbg     /* profiling: raster counter at each milestone */
        addq.l  #1,rt_ticks
        bsr     io_update
        /* run the arcade IRQ handler on the runtime stack with a fake exception frame */
        move.l  sp,rt_saved_sp
        lea     RT_STACK,sp
        pea     arc_irq_done
        move    sr,-(sp)
        jmp     ARC_IRQ6
arc_irq_done:
        move.w  REG_LSPCMODE,rt_dbg+2
        bsr     palette_sync
        move.w  REG_LSPCMODE,rt_dbg+4
        bsr     video_frame
        move.w  REG_LSPCMODE,rt_dbg+6
        bsr     diag_frame
        move.l  rt_saved_sp,sp
        rts

* ------------------------------------------------------------------------------------------
* Diagnostic overlay (hold D for one second to toggle it): the protection sums and sabotage flags of
* the arcade program and the ticks skipped, on the fix layer.  "OK" / "MAL" compares a sum with the
* value of the original program.  Queued like any other VRAM change.
* ------------------------------------------------------------------------------------------
        .equ    DIAG_N, 19
diag_frame:
        move.b  BIOS_P1CURRENT,d0
        btst    #7,d0
        beq.s   1f
        addq.b  #1,rt_diag_hold
        cmpi.b  #60,rt_diag_hold
        bne.s   2f
        not.b   rt_diag_on
        bne.s   2f
        st      rt_diag_clr
        bra.s   2f
1:      clr.b   rt_diag_hold
2:      tst.b   rt_diag_on
        bne.s   3f
        tst.b   rt_diag_clr
        bne.s   3f
        rts
3:      movea.l rt_vcmd_ptr,a6
        cmpa.l  #VCMD_BUF,a6
        bcc.s   4f
        lea     VCMD_BUF,a6
4:      lea     diag_tab,a0
        moveq   #0,d7                   /* line */
dg_line:
        jsr     vc_room
        move.w  d7,d0
        addq.w  #7,d0                   /* row (below the HUD) */
        add.w   #VRAM_FIX+2*32,d0       /* column 2 */
        move.w  d0,(a6)+
        move.w  #32,(a6)+
        move.w  #17-1,(a6)+
        tst.b   rt_diag_on
        bne.s   5f
        moveq   #16,d0                  /* turned off: blank the line */
6:      move.w  #0x00FF,(a6)+
        dbra    d0,6b
        lea     14(a0),a0
        bra     dg_next
5:      moveq   #3,d0                   /* label */
7:      moveq   #0,d1
        move.b  (a0)+,d1
        or.w    #(PAL_FIX<<12)&0xFFFF,d1
        move.w  d1,(a6)+
        dbra    d0,7b
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        movea.l (a0)+,a1                /* address */
        move.w  (a0)+,d1                /* size: 1, 2 or 4 */
        move.l  (a0)+,d4                /* expected (0 = none) */
        moveq   #0,d2
        cmpi.w  #4,d1
        bne.s   8f
        move.l  (a1),d2
        moveq   #7,d3
        bra.s   10f
8:      move.w  (a1),d2
        swap    d2
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        moveq   #3,d3
10:     rol.l   #4,d2
        moveq   #15,d0
        and.w   d2,d0
        move.b  diag_hex(pc,d0.w),d0
        or.w    #(PAL_FIX<<12)&0xFFFF,d0
        move.w  d0,(a6)+
        dbra    d3,10b
        move.w  #(PAL_FIX<<12)+0x20,(a6)+
        lea     diag_none(pc),a2
        tst.l   d4
        beq.s   11f
        lea     diag_ok(pc),a2
        cmp.l   (a1),d4
        beq.s   11f
        lea     diag_bad(pc),a2
11:     moveq   #2,d0
12:     moveq   #0,d1
        move.b  (a2)+,d1
        or.w    #(PAL_FIX<<12)&0xFFFF,d1
        move.w  d1,(a6)+
        dbra    d0,12b
dg_next:
        addq.w  #1,d7
        cmpi.w  #DIAG_N,d7
        bcs     dg_line
        move.l  a6,rt_vcmd_ptr
        tst.b   rt_diag_on
        bne.s   13f
        clr.b   rt_diag_clr
13:     rts
diag_hex:
        .ascii  "0123456789ABCDEF"
diag_ok:
        .ascii  " OK"
diag_bad:
        .ascii  "MAL"
diag_none:
        .ascii  "   "
        .align  2
* label (4 chars), address, size, expected value of the original program (0 = not checked)
diag_tab:
        .ascii  "F502"
        .long   ARC_WRAM+0x3502
        .word   4
        .long   0x14AA816C
        .ascii  "F520"
        .long   ARC_WRAM+0x3520
        .word   4
        .long   0xAFC9EA39
        .ascii  "F53C"
        .long   ARC_WRAM+0x353C
        .word   4
        .long   0xC7542125
        .ascii  "F540"
        .long   ARC_WRAM+0x3540
        .word   4
        .long   0x67CE546B
        .ascii  "F846"
        .long   ARC_WRAM+0x3846
        .word   4
        .long   0x1CF15E75
        .ascii  "F80C"
        .long   ARC_WRAM+0x380C
        .word   4
        .long   0
        .ascii  "SUMK"
        .long   0xF0A00
        .word   4
        .long   0
        .ascii  "F81E"
        .long   ARC_WRAM+0x381E
        .word   4
        .long   0xA209E4F1
        .ascii  "F54E"
        .long   ARC_WRAM+0x354E
        .word   2
        .long   0
        .ascii  "C162"
        .long   ARC_WRAM+0x162
        .word   2
        .long   0
        .ascii  "C154"
        .long   ARC_WRAM+0x154
        .word   2
        .long   0
        .ascii  "F4B4"
        .long   ARC_WRAM+0x34B4
        .word   2
        .long   0
        .ascii  "F4BA"
        .long   ARC_WRAM+0x34BA
        .word   2
        .long   0
        .ascii  "C230"
        .long   ARC_WRAM+0x230
        .word   2
        .long   0
        .ascii  "C22E"
        .long   ARC_WRAM+0x22E
        .word   2
        .long   0
        .ascii  "F556"
        .long   ARC_WRAM+0x3556
        .word   2
        .long   0
        .ascii  "EAE8"
        .long   ARC_WRAM+0x2AE8
        .word   2
        .long   0
        .ascii  "EAF2"
        .long   ARC_WRAM+0x2AF2
        .word   4
        .long   0
        .ascii  "SKIP"
        .long   rt_skip
        .word   2
        .long   0

* TRAP #1: dispatch an arcade VRAM write (2/4-byte instruction replaced by the trap) to its stub.
* Stack on entry: SR.w, PC.l (PC = address after the trap opcode).
        .global trap1_handler
trap1_handler:
        movem.l d0-d1/a0-a1,-(sp)
        move.l  18(sp),a0               /* return PC */
        lea     trap_table,a1
1:      move.l  (a1),d0
        beq     trap_error_pc
        cmp.l   d0,a0
        beq     2f
        lea     12(a1),a1
        bra     1b
2:      move.l  8(a1),d0
        add.l   d0,18(sp)               /* skip the padding after the trap */
        move.l  4(a1),rt_trap_stub
        movem.l (sp)+,d0-d1/a0-a1
        pea     trap1_rte
        move.l  rt_trap_stub,-(sp)
        rts                             /* -> stub, which returns to trap1_rte */
trap1_rte:
        rte
trap_error_pc:
        movem.l (sp)+,d0-d1/a0-a1
        jmp     trap_error

* palette_sync: arcade palette RAM shadow (xBRG444, entries 0..1023) -> ARC_PAL (Neo Geo format) for
* the 16-colour palettes whose raw words changed since the last call.
* Half of the 64 palettes is checked per frame (alternating), so a change shows up at most two frames
* later; the compare is 8 cmpm.l per palette with an early exit on the first difference.
palette_sync:
        lea     ARC_PALRAW,a0
        lea     ARC_PALLAST,a1
        lea     ARC_PAL,a2
        lea     rt_pal_dirty,a3
        lea     pal_table,a4
        not.b   rt_pal_half                 /* alternate halves per call (not per VBlank: a long frame skips the */
        beq.s   1f                          /* next tick, and a VBlank parity would always pick the same half) */
        lea     1024(a0),a0             /* odd frames: palettes 32..63 */
        lea     1024(a1),a1
        lea     1024(a2),a2
        lea     32(a3),a3
1:      moveq   #31,d7
ps_pal:
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        cmpm.l  (a0)+,(a1)+
        bne.s   ps_conv
        lea     32(a2),a2
        addq.l  #1,a3
        dbra    d7,ps_pal
        rts
ps_conv:
        /* back to the start of this palette and convert its 16 entries (a1 is past the differing long,
           which may be the last one of the palette: step back before rounding down) */
        move.l  a1,d0
        subq.l  #4,d0
        sub.l   #ARC_PALLAST,d0
        and.w   #0xFFE0,d0
        lea     ARC_PALLAST,a1
        adda.l  d0,a1
        lea     ARC_PALRAW,a0
        adda.l  d0,a0
        moveq   #15,d6
1:      move.w  (a0)+,d0
        move.w  d0,(a1)+
        and.w   #0x0FFF,d0
        add.w   d0,d0
        move.w  (a4,d0.w),(a2)+
        dbra    d6,1b
        st      (a3)+
        st      rt_pal_any
        dbra    d7,ps_pal
        rts

* selftest_decrypt: decrypt a few known pairs into rt_test_out so the MAME harness can check decrypt_long
selftest_decrypt:
        lea     test_vals(pc),a0
        lea     rt_test_out,a1
        moveq   #5,d1
1:      move.l  (a0)+,d0
        jsr     decrypt_long
        move.l  d0,(a1)+
        dbra    d1,1b
        rts
test_vals:
        .long   0x4D0FF8A6, 0x40544454, 0x095DB400, 0x4054EBE5, 0x3A3F3D18, 0xC8411F0E
        .align  2

* ------------------------------------------------------------------------------------------
* Fast replacements for the arcade routines that write whole blocks of tiles (patched at their
* entry with `jmp` by tools/mkrom.py).  Same register effects as the originals.
* ------------------------------------------------------------------------------------------
        .global blk_copy_l1, blk_copy_l0, clear_l1, clear_l0

* 0x11CF4 / 0x11D62: draw image block d0 at position d4 (row<<8 | column) into layer 1 / layer 0.
* Header (decrypted): bits 0-7 height, 8-15 width, 16-31 offset into the data region.
blk_copy_l1:
        movem.l d5-d7/a0/a3/a6,-(sp)
        lea     0xE5674,a1
        movea.l ARC_WRAM+0x2C3C,a2
        lsl.b   #2,d4
        addi.b  #0x14,d4
        addi.l  #0x102000,d4
        lea     0x1030C0,a3
        moveq   #1,d7                   /* clip at the end of VRAM like the original */
        bra     blk_common
blk_copy_l0:
        movem.l d5-d7/a0/a3/a6,-(sp)
        lea     0xEA1BE,a1
        movea.l ARC_WRAM+0x2C48,a2
        lsl.b   #2,d4
        addi.l  #0x100014,d4
        lea     0x1010A0,a3
        moveq   #0,d7
blk_common:
        lsl.w   #2,d0
        move.l  (a1,d0.w),d0
        move.l  d0,(a3)                 /* the original parks the header in a VRAM cell and reads it back */
        moveq   #0,d3
        move.b  d0,d3                   /* height */
        lsr.w   #8,d0
        moveq   #0,d2
        move.b  d0,d2                   /* width */
        swap    d0
        move.w  d0,d1                   /* data offset (16-bit, sign-extended by the original addressing) */
        movea.l d4,a5
        subq.w  #1,d2
        subq.w  #1,d3
        move.w  d2,d6
        /* the cells go straight to the shadow map; the column sprites showing the block's map columns
           are reloaded whole at the next frame (much cheaper than one queued cell per tile).  They are
           marked after the copy: a VBlank during the copy may load a column half written */
        move.l  a5,d0
        and.w   #0x1FFF,d0
        lsr.w   #2,d0
        and.w   #63,d0                  /* first map column */
        move.w  d6,d5                   /* width - 1 */
        st      rt_col_inval
        lea     rt_col_loaded,a0
        tst.w   d7
        beq.s   blk_row
        lea     24(a0),a0               /* layer 1 */
blk_row:
        movea.l a5,a4
        move.w  d6,d2
blk_col:
        move.l  (a2,d1.w),(a4)+
        addq.w  #4,d1
        tst.w   d7
        beq.s   1f
        cmpa.l  #0x104000,a4
        bge.s   blk_done
1:      dbra    d2,blk_col
        adda.l  #0x100,a5
        tst.w   d7
        beq.s   2f
        cmpa.l  #0x104000,a5
        bge.s   blk_done
2:      dbra    d3,blk_row
blk_done:
        moveq   #NCOLSPR-1,d2
4:      move.b  (a0),d4
        cmpi.b  #0xFF,d4
        beq.s   5f
        sub.b   d0,d4
        and.b   #63,d4
        cmp.b   d5,d4
        bhi.s   5f
        move.b  #0xFF,(a0)              /* inside the block: reload */
5:      addq.l  #1,a0
        dbra    d2,4b
        movem.l (sp)+,d5-d7/a0/a3/a6
        rts

* Map strip copies (patched at 0x9904 / 0x99A0 / 0x9C3C / 0x9CD8 by tools/mkrom.py): the original inner
* block is "dX = C224 & $F0 ; if dX != $90: move.l (a0),(a1) ; step a1" with dX = d7 or d6 and a step of
* 4 (row strip) or $100 (column strip).
        .global strip_h7, strip_v7, strip_h6, strip_v6
strip_h7:
        move.w  ARC_WRAM+0x224,d7
        andi.w  #0xF0,d7
        cmpi.w  #0x90,d7
        beq.s   1f
        bsr.s   strip_store
1:      addq.l  #4,a1
        rts
strip_v7:
        move.w  ARC_WRAM+0x224,d7
        andi.w  #0xF0,d7
        cmpi.w  #0x90,d7
        beq.s   1f
        bsr.s   strip_store
1:      lea     0x100(a1),a1
        rts
strip_h6:
        move.w  ARC_WRAM+0x224,d6
        andi.w  #0xF0,d6
        cmpi.w  #0x90,d6
        beq.s   1f
        bsr.s   strip_store
1:      addq.l  #4,a1
        rts
strip_v6:
        move.w  ARC_WRAM+0x224,d6
        andi.w  #0xF0,d6
        cmpi.w  #0x90,d6
        beq.s   1f
        bsr.s   strip_store
1:      lea     0x100(a1),a1
        rts
* strip_store: a0 -> source pair, a1 -> map cell.  Inline fast path for cells outside the column window
* (most of them: the arcade prepares the map ahead of the scroll), the rest through vram_store.
* Preserves every register.
strip_store:
        move.l  d0,-(sp)
        move.l  (a0),d0
        cmp.l   (a1),d0
        beq.s   8f                      /* same pair */
        move.l  d1,-(sp)
        move    sr,-(sp)
        ori.w   #0x0700,sr              /* check + write atomic with respect to the VBlank column loads */
        move.l  a1,d1
        btst    #13,d1
        bne.s   3f
        lsr.w   #2,d1
        and.w   #63,d1
        sub.w   rt_c0,d1
        bra.s   4f
3:      lsr.w   #2,d1
        and.w   #63,d1
        sub.w   rt_c0+2,d1
4:      and.w   #63,d1                  /* j = (col - c0) & 63 */
        cmpi.w  #NCOLSPR,d1
        bcs.s   6f                      /* in the window: vram_store */
        move.l  d0,(a1)
        move    (sp)+,sr
        move.l  (sp)+,d1
8:      move.l  (sp)+,d0
        rts
6:      move    (sp)+,sr
        move.l  (sp)+,d1
        movem.l d1-d2/a0-a2,-(sp)
        movea.l a1,a0
        jsr     vram_store
        movem.l (sp)+,d1-d2/a0-a2
        move.l  (sp)+,d0
        rts

* 0x11FDC / 0x11FF2: fill a layer with the empty tile pair (0xDF64C / 0xDF650, decrypted at build time)
clear_l1:
        lea     ARC_VRAM+0x2000,a0
        move.l  0xDF64C,d0
        bsr     clear_fill
        lea     rt_col_loaded+24,a0
        bra     clear_inval
clear_l0:
        lea     ARC_VRAM,a0
        move.l  0xDF650,d0
        bsr     clear_fill
        lea     rt_col_loaded,a0
clear_inval:
        st      rt_col_inval
        moveq   #NCOLSPR-1,d0
1:      move.b  #0xFF,(a0)+             /* column sprites reload at the next frame */
        dbra    d0,1b
        rts
clear_fill:
        movem.l d1-d7,-(sp)
        move.l  d0,d1
        move.l  d0,d2
        move.l  d0,d3
        move.l  d0,d4
        move.l  d0,d5
        move.l  d0,d6
        move.l  d0,d7
        move.w  #255,d0
2:      movem.l d1-d7,(a0)
        move.l  d1,28(a0)
        lea     32(a0),a0
        dbra    d0,2b
        movem.l (sp)+,d1-d7
        rts
